#!/usr/bin/env node
/**
 * Generates src/providers/wordpress/sections.generated.ts from the canonical
 * plugin sections.json. Both the WordPress plugin and the TypeScript provider
 * derive their section vocabulary from that single file.
 *
 * Written to be runnable from any consumer checkout; the generated output is
 * committed so `tsc --noEmit` never depends on this script running.
 *
 * Run with --check to fail (exit 1) when the committed generated file is
 * stale, used by `npm run check:sections`.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sectionsPath = path.join(
  root,
  "integrations/wordpress/nexuscontent/sections.json"
);
const generatedPath = path.join(
  root,
  "src/providers/wordpress/sections.generated.ts"
);

const ALLOWED_FIELD_TYPES = new Set([
  "string",
  "number",
  "boolean",
  "json",
  "media"
]);

function sourceName(type) {
  return String(type).replaceAll("_", "-");
}

function error(message, cause) {
  const e = new Error(message);
  e.cause = cause;
  return e;
}

function loadAndValidate() {
  let raw;
  try {
    raw = JSON.parse(readFileSync(sectionsPath, "utf8"));
  } catch (cause) {
    throw error(`sections.json is not valid JSON: ${sectionsPath}`, cause);
  }

  const sections = raw?.sections;
  if (!Array.isArray(sections) || sections.length === 0) {
    throw new Error("sections.json must contain a non-empty \"sections\" array");
  }

  const types = new Set();
  for (const section of sections) {
    const type = section?.type;
    if (typeof type !== "string" || !/^[a-z0-9_]+$/.test(type)) {
      throw new Error(`section "type" must be a lowercase snake identifier, got: ${JSON.stringify(type)}`);
    }
    if (types.has(type)) {
      throw new Error(`duplicate section type: ${type}`);
    }
    types.add(type);

    if (section.fixed !== undefined && typeof section.fixed !== "boolean") {
      throw new Error(`section "${type}" "fixed" must be a boolean`);
    }
    if (section.label !== undefined && (typeof section.label !== "string" || section.label.trim() === "")) {
      throw new Error(`section "${type}" "label" must be a non-empty string`);
    }
    const fields = section.fields;
    if (!Array.isArray(fields)) {
      throw new Error(`section "${type}" must declare a "fields" array`);
    }
    for (const field of fields) {
      if (typeof field?.name !== "string" || !/^[a-z0-9_]+$/.test(field.name)) {
        throw new Error(`section "${type}" has a field with an invalid "name": ${JSON.stringify(field?.name)}`);
      }
      if (!ALLOWED_FIELD_TYPES.has(field.type)) {
        throw new Error(
          `section "${type}" field "${field.name}" has unsupported type ${JSON.stringify(field.type)}`
        );
      }
      if (field.required !== undefined && typeof field.required !== "boolean") {
        throw new Error(`section "${type}" field "${field.name}" "required" must be a boolean`);
      }
      if (field.default !== undefined && (typeof field.default !== "object" || field.default === null)) {
        if (!["string", "number", "boolean"].includes(typeof field.default)) {
          throw new Error(`section "${type}" field "${field.name}" has an invalid "default"`);
        }
      }
    }
  }

  return { sections, types };
}

function render({ sections }) {
  const fixedTypes = sections.filter((s) => s.fixed === true).map((s) => s.type);
  const unions = sections.map((s) => JSON.stringify(s.type)).join(" | ");

  return `// Generated by scripts/generate-sections.mjs from
// integrations/wordpress/nexuscontent/sections.json. Do not edit by hand.
// Run \`npm run generate:sections\` after changing the JSON; CI enforces
// freshness with \`npm run check:sections\`.

type GeneratedJson = null | boolean | number | string | GeneratedJson[] | { [key: string]: GeneratedJson };

export interface GeneratedSectionFieldDefinition {
  readonly name: string;
  readonly type: "string" | "number" | "boolean" | "json" | "media";
  readonly required?: boolean;
  readonly default?: GeneratedJson;
}

export type GeneratedSectionType = ${unions};

export const WORDPRESS_SECTION_NAMES: Readonly<Record<GeneratedSectionType, string>> = {
${sections.map((s) => `  ${JSON.stringify(s.type)}: ${JSON.stringify(sourceName(s.type))},`).join("\n")}
};

export const BUILTIN_SECTION_FIELDS: Readonly<
  Record<GeneratedSectionType, readonly GeneratedSectionFieldDefinition[]>
> = {
${sections
    .map(
      (s) => `  ${JSON.stringify(s.type)}: [
${s.fields
      .map(
        (f) => `    { name: ${JSON.stringify(f.name)}, type: ${JSON.stringify(f.type)}${f.required ? ", required: true" : ""}${f.default !== undefined ? `, default: ${JSON.stringify(f.default)}` : ""} }`
      )
      .join(",\n")}
  ],`
    )
    .join("\n")}
};

export const FIXED_SECTION_TYPES = [${fixedTypes.map((t) => JSON.stringify(t)).join(", ")}] as const;
`;
}

let output;
try {
  output = render(loadAndValidate());
} catch (cause) {
  console.error(cause instanceof Error ? cause.message : cause);
  process.exit(1);
}

if (process.argv.includes("--check")) {
  let committed = null;
  try {
    committed = readFileSync(generatedPath, "utf8");
  } catch {
    // Falls through to the stale check below.
  }
  if (committed !== output) {
    console.error("sections.generated.ts is stale. Run `npm run generate:sections`.");
    process.exit(1);
  }
  console.log("sections.generated.ts is up to date.");
} else {
  writeFileSync(generatedPath, output);
  console.log(`Wrote ${path.relative(root, generatedPath)}`);
}